import { forwardRef, useImperativeHandle, useMemo, useRef, type ComponentProps, type ReactNode } from "react";
import { Interactive, Sequence, random, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

// A component's schedule, kept apart from its drawing: which elements the
// animation has (an entry, a word, a finale), when each starts and how long
// it runs. The schedule is a pure function of the props, so it can be read
// without rendering anything, and a `timing` prop can move, trim or stretch
// single elements without touching the code that draws them.
//
//   // timeline.ts, next to the component
//   export const titleTimeline = defineTimeline<TitleElementId, TitleProps>(
//     ({ words = WORDS }, { length }) =>
//       words.map((word, k) => ({
//         id: `word:${k}`,
//         lane: "Words",
//         label: word,
//         start: k * 8,
//         length: 8,
//         follows: k > 0 ? `word:${k - 1}` : undefined,
//         beats: { rise: 12 },
//       })),
//   );
//
//   // index.tsx
//   const tl = useTimeline(titleTimeline, props, length, timing);
//   const word = tl.get("word:0");
//   interpolate(t, [word.start, word.start + word.beat("rise")], [0, 1]);
//
// Every number is in frames of the 30 fps scene timeline, after `delay` and
// `speed`: those still apply to the whole animation, `timing` works inside it.
// Element ids are public API: a saved `timing` refers to them, so an id once
// shipped keeps its meaning.

/** One timed part of an animation, as its schedule lays it out. */
interface TimelineElement<Id extends string = string> {
  /** Stable name a `timing` override refers to: `entry:0`, `finale`. */
  id: Id;
  /** Row the element sits on in a timeline view. */
  lane: string;
  /** What the element shows, for people reading the timeline. */
  label: string;
  /** First frame of the element. */
  start: number;
  /** Frames until the next element of the lane takes over, or the end. */
  length: number;
  /**
   * The element this one comes after. When that element's end moves, this
   * one moves with it, keeping the gap between them.
   */
  follows?: Id;
  /**
   * Named frame counts inside the element, measured from its start: how long
   * a roll takes, when a second part begins. `stretch` scales them.
   */
  beats?: Record<string, number>;
}

/** A change to one element, made from outside the component. */
interface TimingOverride {
  /** New first frame. Wins over the shift from `follows`. */
  start?: number;
  /** New length, trimming or extending the element. Wins over `stretch`. */
  length?: number;
  /** Multiplies the length and every beat: 2 plays the element half as fast. */
  stretch?: number;
  /** Stops following: the element keeps its own start when the one before moves. */
  detach?: boolean;
}

/** Overrides by element id: the `timing` prop of a component. */
type Timing<Id extends string = string> = Partial<
  Record<Id, TimingOverride>
>;

/** A component's schedule: props and the scene length in, elements out. */
type Schedule<Id extends string, Props> = (
  props: Props,
  scene: { length: number },
) => TimelineElement<Id>[];

/** An element after `timing` has been applied. */
interface ResolvedElement<Id extends string = string>
  extends TimelineElement<Id> {
  /** `start + length`. */
  end: number;
  beats: Record<string, number>;
  /** A beat by name, stretched. Throws on a name the schedule didn't set. */
  beat(name: string): number;
  /**
   * 0 → 1 over the element, or over its first `beat` frames when a beat is
   * named. Clamped on both sides.
   */
  progress(frame: number, beat?: string): number;
}

interface ResolvedTimeline<Id extends string = string> {
  /** All elements, in the order the schedule returned them. */
  elements: ResolvedElement<Id>[];
  /** An element by id. Throws on an id the schedule didn't return. */
  get(id: Id): ResolvedElement<Id>;
  /** The elements of one lane, in order. */
  lane(name: string): ResolvedElement<Id>[];
}

/** Declares a schedule. Elements come back in time order. */
function defineTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
): Schedule<Id, Props> {
  return schedule;
}

/** Applies `timing` to a schedule's elements and carries the `follows` chains. */
function resolve<Id extends string>(
  elements: TimelineElement<Id>[],
  timing: Timing<Id> = {},
): ResolvedTimeline<Id> {
  const byId = new Map<Id, TimelineElement<Id>>(elements.map((e) => [e.id, e]));
  const done = new Map<Id, ResolvedElement<Id>>();
  const visiting = new Set<Id>();

  const place = (element: TimelineElement<Id>): ResolvedElement<Id> => {
    const known = done.get(element.id);
    if (known) return known;
    if (visiting.has(element.id)) {
      throw new Error(`timeline: "${element.id}" follows itself`);
    }
    visiting.add(element.id);

    const override: TimingOverride = timing[element.id] ?? {};
    const stretch = override.stretch ?? 1;
    const beats: Record<string, number> = {};
    for (const [name, frames] of Object.entries(element.beats ?? {})) {
      beats[name] = frames * stretch;
    }

    let start = element.start;
    const leader = element.follows ? byId.get(element.follows) : undefined;
    if (leader && !override.detach) {
      // The leader's end moved by this much; this element moves as far.
      start += place(leader).end - (leader.start + leader.length);
    }
    if (override.start !== undefined) start = override.start;
    const length = override.length ?? element.length * stretch;

    const beat = (name: string) => {
      const frames = beats[name];
      if (frames === undefined) {
        throw new Error(`timeline: "${element.id}" has no beat "${name}"`);
      }
      return frames;
    };
    const resolved: ResolvedElement<Id> = {
      ...element,
      start,
      length,
      end: start + length,
      beats,
      beat,
      progress: (frame, name) => {
        const span = name === undefined ? length : beat(name);
        if (span <= 0) return frame >= start ? 1 : 0;
        return Math.min(1, Math.max(0, (frame - start) / span));
      },
    };
    visiting.delete(element.id);
    done.set(element.id, resolved);
    return resolved;
  };

  const all = elements.map(place);
  return {
    elements: all,
    get: (id) => {
      const element = done.get(id);
      if (!element) throw new Error(`timeline: no element "${id}"`);
      return element;
    },
    lane: (name) => all.filter((e) => e.lane === name),
  };
}

/**
 * The component side: runs the schedule and applies `timing`, once per
 * change of its inputs. `length` is the scene length the schedule fits into,
 * in the same frames the component counts.
 */
function useTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
  props: Props,
  length: number,
  timing?: Timing<Id>,
): ResolvedTimeline<Id> {
  return useMemo(
    () => resolve(schedule(props, { length }), timing),
    [schedule, props, length, timing],
  );
}

// Trail mode: the subject travels to its target and settles on a spring.
// Focus mode: the lines rush in to the focus point, hold, then release.
// Frames on the 30 fps scene timeline, after `delay` and `speed`. The ids are
// public: a saved `timing` prop refers to them.

type SpeedLinesElementId = "travel" | "settle" | "rush" | "release";

interface SpeedLinesTimingProps {
  mode?: string;
  duration?: number;
  bounce?: number;
}

const DURATION = 14;
const BOUNCE = 0.5;
const MIN_DURATION = 4;
const MAX_DURATION = 120;
const LANDING = 0.3;
const CARRY = 0.3;
const ECHO = 0.2;
const SOFTEN = 1.2;
const SETTLE = 6;
/** Frame the focus lines reach their rest radius. */
const IMPACT = 3;
/** How late, at most, a focus line starts its rush. */
const RUSH_JITTER = 1;
/** Frame the focus lines start to retract. */
const RELEASE = 8;
/** How late, at most, a focus line starts its retract. */
const RELEASE_JITTER = 1.5;
/** Frames a focus line takes to retract. */
const RETRACT = 3.5;
const FOCUS_END = RELEASE + RELEASE_JITTER + RETRACT;

const finite$own = (value: number | undefined, fallback: number) =>
  typeof value === "number" && Number.isFinite(value) ? value : fallback;
const clamp$own = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

const modeOf = (value: string | undefined) =>
  value === "focus" ? ("focus" as const) : ("trail" as const);
const travelOf = (value: number | undefined) =>
  clamp$own(finite$own(value, DURATION), MIN_DURATION, MAX_DURATION);
const bounceOf = (value: number | undefined) =>
  clamp$own(finite$own(value, BOUNCE), 0, 1);

function springOf(bounce: number) {
  const landing = LANDING + CARRY * bounce;
  const kappa = (1 + Math.sqrt(1 - landing)) / 2;
  const gain = 1 / (0.5 - kappa / 3);
  const echo = ECHO * bounce;
  const decrement = -Math.log(echo);
  const damping = echo > 0 ? decrement / Math.hypot(Math.PI, decrement) : 1;
  const natural = 1 / (1 + SOFTEN * bounce);
  const decay = damping * natural;
  return {
    kappa,
    gain,
    contact: gain * (1 - kappa),
    decay,
    ring: natural * Math.sqrt(1 - damping * damping),
    settle: Math.ceil(SETTLE / decay),
  };
}

// The trail's travel ends on landing; the settle is the spring ringing out
// after it. The focus rush ends on impact; the release starts the earliest
// retract, each line's own lateness (`jitter`) and its retract are beats.
const speedLinesTimeline = defineTimeline<
  SpeedLinesElementId,
  SpeedLinesTimingProps
>(({ mode, duration, bounce }): TimelineElement<SpeedLinesElementId>[] => {
  if (modeOf(mode) === "focus") {
    return [
      {
        id: "rush",
        lane: "Lines",
        label: "rush in",
        start: 0,
        length: IMPACT,
        beats: { jitter: RUSH_JITTER },
      },
      {
        id: "release",
        lane: "Lines",
        label: "release",
        start: RELEASE,
        length: RELEASE_JITTER + RETRACT,
        follows: "rush",
        beats: { jitter: RELEASE_JITTER, retract: RETRACT },
      },
    ];
  }
  const travel = travelOf(duration);
  return [
    {
      id: "travel",
      lane: "Subject",
      label: "travel",
      start: 0,
      length: travel,
    },
    {
      id: "settle",
      lane: "Subject",
      label: "settle",
      start: travel,
      length: springOf(bounceOf(bounce)).settle,
      follows: "travel",
    },
  ];
});

type SpeedLinesMode = "trail" | "focus";

interface SpeedLinesPoint {
  x: number;
  y: number;
}

interface SpeedLinesProps {
  mode?: SpeedLinesMode;
  from?: SpeedLinesPoint;
  to?: SpeedLinesPoint;
  x?: number;
  y?: number;
  count?: number;
  weight?: number;
  spread?: number;
  duration?: number;
  bounce?: number;
  squash?: number;
  color?: string;
  seed?: number;
  delay?: number;
  speed?: number;
  children?: ReactNode;
  className?: string;
  /**
   * Moves, trims or stretches the travel and settle (trail mode) or the
   * rush and release (focus mode), by the ids in `./timeline`.
   * Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<SpeedLinesElementId>;
}

type Paint = "color" | "children" | "className";
type Unset = "to" | "children" | "className" | "timing";

interface SpeedLinesOptions extends Omit<SpeedLinesProps, Paint> {
  width?: number;
  height?: number;
  fps?: number;
  /** The resolved schedule; without it the options' `timing` is applied. */
  timeline?: ResolvedTimeline<SpeedLinesElementId>;
}

interface SpeedLinesSegment {
  index: number;
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  length: number;
}

interface SpeedLinesStreak extends SpeedLinesSegment {
  offset: number;
  reach: number;
}

interface SpeedLinesRay extends SpeedLinesSegment {
  angle: number;
  rest: number;
  inner: number;
  outer: number;
}

interface SpeedLinesRayTiming {
  rest: number;
  outer: number;
  start?: number;
  release?: number;
  impact?: number;
  retract?: number;
}

const speedLinesDefaults: Required<Omit<SpeedLinesProps, Unset>> = {
  mode: "trail",
  from: { x: -0.25, y: 0.5 },
  x: 0.5,
  y: 0.5,
  count: 12,
  weight: 2,
  spread: 96,
  duration: 14,
  bounce: 0.5,
  squash: 0.5,
  color: "#ffffff",
  seed: 1,
  delay: 0,
  speed: 1,
};

const REFERENCE = 720;
const STRETCH = Math.log(1.3);
const SQUASH = Math.log(1.25);
const STRETCH_GAIN = 0.007;
const SQUASH_GAIN = 0.018;
const PROBE = 1e-3;
const CENTER = "translate(-50%, -50%)";
const HOLD = 24;
const SPAWN_START = 0.04;
const SPAWN_END = 0.8;
const LIFE = 0.3;
const MIN_LIFE = 3;
const DRAW = 0.4;
const ERASE = 0.35;
const SHUTTER = 1.6;
const DRIFT = 0.15;
const SETBACK = 0.35;
const SLOW = 5;
const FAST = 14;
const GOLDEN = (Math.sqrt(5) - 1) / 2;
const RELAX = 0.12;
const RELAX_RATE = 1.5;
const ANGLE_JITTER = 0.6;
const RADIUS_JITTER = 0.6;
const MAX_COUNT = 64;
const MIN_WEIGHT = 0.5;
const MAX_WEIGHT = 12;
const MIN_SPREAD = 8;
const MAX_SPREAD = 480;

const finite = (value: number | undefined, fallback: number) =>
  typeof value === "number" && Number.isFinite(value) ? value : fallback;
const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));
const round = (value: number) => Math.round(value * 100) / 100;
const fine = (value: number) => Math.round(value * 10000) / 10000;
const fraction = (value: number) => value - Math.floor(value);

function smoothstep(value: number) {
  const t = clamp(value, 0, 1);
  return t * t * (3 - 2 * t);
}

function easeOut(value: number) {
  const t = clamp(value, 0, 1);
  return 1 - (1 - t) * (1 - t);
}

function pointOf(
  value: SpeedLinesPoint | undefined,
  fallback: SpeedLinesPoint,
) {
  return { x: finite(value?.x, fallback.x), y: finite(value?.y, fallback.y) };
}

function key(seed: number, index: number, name: string) {
  return random(`speed-lines-${seed}-${index}-${name}`);
}

// The element spans the drawing reads, from the resolved schedule.
function spansOf(options: SpeedLinesOptions, mode: SpeedLinesMode) {
  const tl =
    options.timeline ??
    resolve(speedLinesTimeline(options, { length: 0 }), options.timing);
  if (mode === "focus") {
    const rush = tl.get("rush");
    const release = tl.get("release");
    return {
      travelStart: 0,
      duration: travelOf(options.duration),
      gap: 0,
      settle: undefined,
      impact: rush.end,
      end: release.end,
      rushStart: rush.start,
      rushJitter: rush.beat("jitter"),
      release: release.start,
      releaseJitter: release.beat("jitter"),
      retract: release.beat("retract"),
    };
  }
  const travel = tl.get("travel");
  const settle = tl.get("settle");
  return {
    travelStart: travel.start,
    duration: travel.length,
    gap: settle.start - travel.end,
    settle: settle.length,
    impact: travel.end,
    end: settle.end,
    rushStart: 0,
    rushJitter: 0,
    release: RELEASE,
    releaseJitter: 0,
    retract: RETRACT,
  };
}

function settingsOf(options: SpeedLinesOptions) {
  const mode = modeOf(options.mode);
  const height = Math.max(1, finite(options.height, 720));
  const x = finite(options.x, speedLinesDefaults.x);
  const y = finite(options.y, speedLinesDefaults.y);
  const count = finite(options.count, speedLinesDefaults.count);
  const weight = finite(options.weight, speedLinesDefaults.weight);
  const spread = finite(options.spread, speedLinesDefaults.spread);
  return {
    ...spansOf(options, mode),
    mode,
    width: Math.max(1, finite(options.width, 1280)),
    height,
    fps: Math.max(1, finite(options.fps, 30)),
    unit: height / REFERENCE,
    from: pointOf(options.from, speedLinesDefaults.from),
    to: pointOf(options.to, { x, y }),
    x,
    y,
    count: Math.round(clamp(count, 1, MAX_COUNT)),
    weight: clamp(weight, MIN_WEIGHT, MAX_WEIGHT),
    spread: clamp(spread, MIN_SPREAD, MAX_SPREAD),
    bounce: bounceOf(options.bounce),
    squash: clamp(finite(options.squash, speedLinesDefaults.squash), 0, 1),
    seed: finite(options.seed, speedLinesDefaults.seed),
    delay: Math.max(0, finite(options.delay, speedLinesDefaults.delay)),
    speed: Math.max(0, finite(options.speed, speedLinesDefaults.speed)),
  };
}

type Settings = ReturnType<typeof settingsOf>;

function directionOf(settings: Settings) {
  const { from, to, width, height } = settings;
  const dx = (to.x - from.x) * width;
  const dy = (to.y - from.y) * height;
  const distance = Math.hypot(dx, dy);
  if (distance < 1e-6) return { dx: 1, dy: 0, distance: 0 };
  return { dx: dx / distance, dy: dy / distance, distance };
}

function along(position: number, size: number, step: number) {
  if (step > 1e-9) return (size - position) / step;
  if (step < -1e-9) return -position / step;
  return Number.POSITIVE_INFINITY;
}

function exitDistance(
  cx: number,
  cy: number,
  cos: number,
  sin: number,
  width: number,
  height: number,
) {
  const inside = cx >= 0 && cx <= width && cy >= 0 && cy <= height;
  if (!inside) {
    const reachX = Math.max(Math.abs(cx), Math.abs(width - cx));
    const reachY = Math.max(Math.abs(cy), Math.abs(height - cy));
    return Math.hypot(reachX, reachY);
  }
  return Math.min(along(cx, width, cos), along(cy, height, sin));
}

// `gap` holds the landing before the settle starts; `span` is the settle's
// length when `timing` trimmed or stretched it.
function easeOf(
  time: number,
  travel: number,
  bounce: number,
  gap = 0,
  span?: number,
) {
  if (time <= 0) return 0;
  const { kappa, gain, contact, decay, ring, settle } = springOf(bounce);
  if (time < travel) {
    const w = time / travel;
    return gain * ((w * w) / 2 - (kappa * w * w * w) / 3);
  }
  const late = time - travel - gap;
  if (late < 0) return 1;
  const since = span === undefined ? late : late * (settle / span);
  if (since >= settle) return 1;
  const taper = smoothstep((2 * since) / settle - 1);
  const wave = ring > 1e-9 ? Math.sin(ring * since) / ring : since;
  const envelope = Math.exp(-decay * since) * (1 - taper);
  return 1 + (contact / travel) * wave * envelope;
}

function getSpeedLinesTimeline(options: SpeedLinesOptions = {}) {
  const { mode, impact, end } = settingsOf(options);
  return { mode, impact, end };
}

type SpeedLinesTimeline = ReturnType<typeof getSpeedLinesTimeline>;

const speedLinesLength = getSpeedLinesTimeline().end;

function getSpeedLinesDuration(options: SpeedLinesOptions = {}) {
  const { delay, speed } = settingsOf(options);
  if (speed === 0) return 1;
  const { end } = getSpeedLinesTimeline(options);
  return Math.max(1, Math.ceil(delay + (end + HOLD) / speed));
}

function getSpeedLinesTime(
  frame: number,
  options: SpeedLinesOptions = {},
) {
  const { fps, delay, speed } = settingsOf(options);
  const elapsed = Math.max(0, finite(frame, 0) - delay);
  return elapsed * (30 / fps) * speed;
}

function getSpeedLinesEase(
  time: number,
  options: SpeedLinesOptions = {},
) {
  const { travelStart, duration, bounce, gap, settle } = settingsOf(options);
  return easeOf(finite(time, 0) - travelStart, duration, bounce, gap, settle);
}

function positionAt(time: number, settings: Settings) {
  const { mode, from, to, width, height, duration, bounce } = settings;
  if (mode === "focus") {
    return { x: settings.x * width, y: settings.y * height, progress: 1 };
  }
  const { travelStart, gap, settle } = settings;
  const progress = easeOf(time - travelStart, duration, bounce, gap, settle);
  const startX = from.x * width;
  const startY = from.y * height;
  return {
    x: startX + (to.x * width - startX) * progress,
    y: startY + (to.y * height - startY) * progress,
    progress,
  };
}

function getSpeedLinesPosition(
  time: number,
  options: SpeedLinesOptions = {},
) {
  const { x, y } = positionAt(finite(time, 0), settingsOf(options));
  return { x, y };
}

function shapeAt(at: number, settings: Settings) {
  const { mode, duration, bounce, squash, unit, speed } = settings;
  if (mode === "focus") return { rotation: 0, along: 1, across: 1 };
  const { gap, settle } = settings;
  const time = at - settings.travelStart;
  const { dx, dy, distance } = directionOf(settings);
  const rotation = (Math.atan2(dy, dx) * 180) / Math.PI;
  if (squash === 0 || distance === 0 || time <= 0) {
    return { rotation, along: 1, across: 1 };
  }
  const span = distance / unit;
  const ahead = easeOf(time + PROBE, duration, bounce, gap, settle);
  const behind = easeOf(time - PROBE, duration, bounce, gap, settle);
  const rate = (Math.abs(ahead - behind) / (2 * PROBE)) * span * speed;
  const landed =
    time > duration ? easeOf(time, duration, bounce, gap, settle) - 1 : 0;
  const past = Math.max(0, landed) * span;
  const stretch = STRETCH * Math.tanh((squash * STRETCH_GAIN * rate) / STRETCH);
  const compression =
    SQUASH * Math.tanh((squash * SQUASH_GAIN * past) / SQUASH);
  const strain = clamp(stretch - compression, -SQUASH, STRETCH);
  return { rotation, along: Math.exp(strain), across: Math.exp(-strain) };
}

function getSpeedLinesShape(
  time: number,
  options: SpeedLinesOptions = {},
) {
  return shapeAt(finite(time, 0), settingsOf(options));
}

type SpeedLinesShape = ReturnType<typeof getSpeedLinesShape>;

function getSpeedLinesVelocity(
  frame: number,
  options: SpeedLinesOptions = {},
) {
  const settings = settingsOf(options);
  const current = finite(frame, 0);
  const now = positionAt(getSpeedLinesTime(current, options), settings);
  const before = positionAt(getSpeedLinesTime(current - 1, options), settings);
  const scale = settings.fps / 30;
  const x = (now.x - before.x) * scale;
  const y = (now.y - before.y) * scale;
  const { dx, dy } = directionOf(settings);
  return { x, y, forward: x * dx + y * dy };
}

function streakSeeds(settings: Settings) {
  const { seed, count, spread, unit } = settings;
  const band = spread * unit;
  const phase = random(`speed-lines-${seed}-lanes`);
  return Array.from({ length: count }, (_, index) => {
    const jitter = (key(seed, index, "lane") - 0.5) / (2 * count);
    const lane = fraction(phase + GOLDEN * index + jitter);
    const slot = (index + key(seed, index, "spawn")) / count;
    return {
      index,
      spawn: SPAWN_START + (SPAWN_END - SPAWN_START) * slot,
      offset: band * (lane - 0.5),
      factor: 0.5 + 0.5 * key(seed, index, "length"),
      setback: SETBACK * band * key(seed, index, "setback"),
    };
  });
}

function getSpeedLinesStreaks(
  frame: number,
  options: SpeedLinesOptions = {},
): SpeedLinesStreak[] {
  const settings = settingsOf(options);
  if (settings.mode !== "trail") return [];
  const at = getSpeedLinesTime(frame, options);
  const time = at - settings.travelStart;
  const { dx, dy, distance } = directionOf(settings);
  if (distance === 0 || time <= 0) return [];
  const { forward } = getSpeedLinesVelocity(frame, options);
  const { unit, duration, bounce, weight } = settings;
  const fast = smoothstep((forward - SLOW * unit) / ((FAST - SLOW) * unit));
  const gate = fast * (1 - smoothstep(time - duration));
  if (gate <= 0) return [];
  const center = positionAt(at, settings);
  const progress = time / duration;
  const life = Math.max(MIN_LIFE, LIFE * duration) / duration;
  const minimum = 0.5 * weight * unit;
  const streaks: SpeedLinesStreak[] = [];
  for (const streak of streakSeeds(settings)) {
    const age = (progress - streak.spawn) / life;
    if (age <= 0 || age >= 1) continue;
    const reach = SHUTTER * streak.factor * forward * gate;
    const drawn = easeOut(age / DRAW);
    const erased = smoothstep((age - ERASE) / (1 - ERASE));
    const length = reach * (drawn - erased);
    if (length < minimum) continue;
    const spawned = easeOf(streak.spawn * duration, duration, bounce);
    const since = Math.max(0, (center.progress - spawned) * distance);
    const base = streak.setback + DRIFT * since;
    const front = base + reach * erased;
    const back = base + reach * drawn;
    const laneX = center.x - dy * streak.offset;
    const laneY = center.y + dx * streak.offset;
    streaks.push({
      index: streak.index,
      offset: streak.offset,
      reach,
      x1: round(laneX - dx * front),
      y1: round(laneY - dy * front),
      x2: round(laneX - dx * back),
      y2: round(laneY - dy * back),
      length,
    });
  }
  return streaks;
}

function getSpeedLinesRadius(time: number, ray: SpeedLinesRayTiming) {
  const {
    rest,
    outer,
    start = 0,
    release = RELEASE,
    impact = IMPACT,
    retract = RETRACT,
  } = ray;
  const t = finite(time, 0);
  if (t <= start) return outer;
  if (t < impact) {
    const q = (t - start) / (impact - start);
    return outer + (rest - outer) * q * q;
  }
  const settle = (at: number) =>
    rest * (1 + RELAX * (1 - Math.exp(-(at - impact) / RELAX_RATE)));
  if (t < release) return settle(t);
  const held = settle(release);
  const q = clamp((t - release) / retract, 0, 1);
  return outer - (outer - held) * (1 - q * q);
}

function getSpeedLinesRays(
  frame: number,
  options: SpeedLinesOptions = {},
): SpeedLinesRay[] {
  const settings = settingsOf(options);
  if (settings.mode !== "focus") return [];
  const time = getSpeedLinesTime(frame, options);
  if (time <= settings.rushStart || time >= settings.end) return [];
  const { seed, count, spread, weight, unit, width, height } = settings;
  const cx = settings.x * width;
  const cy = settings.y * height;
  const minimum = 0.5 * weight * unit;
  const rotation = random(`speed-lines-${seed}-rotation`);
  const rays: SpeedLinesRay[] = [];
  for (let index = 0; index < count; index++) {
    const jitter = ANGLE_JITTER * (key(seed, index, "angle") - 0.5);
    const angle = 2 * Math.PI * (rotation + (index + jitter) / count);
    const cos = Math.cos(angle);
    const sin = Math.sin(angle);
    const reach = RADIUS_JITTER * key(seed, index, "radius");
    const rest = spread * unit * (1 + reach);
    const outer = exitDistance(cx, cy, cos, sin, width, height) + weight * unit;
    const inner = getSpeedLinesRadius(time, {
      rest,
      outer,
      start:
        settings.rushStart + settings.rushJitter * key(seed, index, "rush"),
      release:
        settings.release + settings.releaseJitter * key(seed, index, "release"),
      impact: settings.impact,
      retract: settings.retract,
    });
    const length = outer - inner;
    if (length < minimum) continue;
    rays.push({
      index,
      angle,
      rest,
      inner,
      outer,
      x1: round(cx + cos * inner),
      y1: round(cy + sin * inner),
      x2: round(cx + cos * outer),
      y2: round(cy + sin * outer),
      length,
    });
  }
  return rays;
}

function getSpeedLinesState(
  frame: number,
  options: SpeedLinesOptions = {},
) {
  const settings = settingsOf(options);
  const time = getSpeedLinesTime(frame, options);
  const point = positionAt(time, settings);
  const shape = shapeAt(time, settings);
  const rotation = round(shape.rotation);
  const scale = `scale(${fine(shape.along)}, ${fine(shape.across)})`;
  const streaks = getSpeedLinesStreaks(frame, options);
  const rays = getSpeedLinesRays(frame, options);
  const path = [...streaks, ...rays]
    .map(({ x1, y1, x2, y2 }) => `M ${x1} ${y1} L ${x2} ${y2}`)
    .join(" ");
  return {
    mode: settings.mode,
    width: settings.width,
    height: settings.height,
    unit: settings.unit,
    time,
    x: point.x,
    y: point.y,
    left: (point.x / settings.width) * 100,
    top: (point.y / settings.height) * 100,
    radius: (settings.spread * settings.unit) / 2,
    strokeWidth: settings.weight * settings.unit,
    rotation,
    along: shape.along,
    across: shape.across,
    transform:
      shape.along === 1
        ? CENTER
        : `${CENTER} rotate(${rotation}deg) ${scale} rotate(${-rotation}deg)`,
    streaks,
    rays,
    path,
  };
}

type SpeedLinesState = ReturnType<typeof getSpeedLinesState>;

function SpeedLinesBase(props: SpeedLinesProps) {
  const {
    mode = speedLinesDefaults.mode,
    from = speedLinesDefaults.from,
    to,
    x = speedLinesDefaults.x,
    y = speedLinesDefaults.y,
    count = speedLinesDefaults.count,
    weight = speedLinesDefaults.weight,
    spread = speedLinesDefaults.spread,
    duration = speedLinesDefaults.duration,
    bounce = speedLinesDefaults.bounce,
    squash = speedLinesDefaults.squash,
    color = speedLinesDefaults.color,
    seed = speedLinesDefaults.seed,
    delay = speedLinesDefaults.delay,
    speed = speedLinesDefaults.speed,
    children,
    className,
    timing,
  } = props;
  const frame = useSceneFrame();
  const { width, height, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    speedLinesTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const state = getSpeedLinesState(frame, {
    mode,
    from,
    to,
    x,
    y,
    count,
    weight,
    spread,
    duration,
    bounce,
    squash,
    seed,
    delay,
    speed,
    width,
    height,
    fps,
    timeline: tl,
  });
  const fallback = state.mode === "trail" && children === undefined;
  const placed = children !== undefined && children !== null;

  return (
    <div
      className={className}
      style={{ position: "absolute", inset: 0, pointerEvents: "none" }}
    >
      <svg
        width="100%"
        height="100%"
        viewBox={`0 0 ${width} ${height}`}
        aria-hidden="true"
        style={{ position: "absolute", inset: 0, display: "block" }}
      >
        {state.path ? (
          <path
            d={state.path}
            fill="none"
            stroke={color}
            strokeWidth={state.strokeWidth}
            strokeLinecap="round"
          />
        ) : null}
        {fallback ? (
          <ellipse
            cx={state.x}
            cy={state.y}
            rx={state.radius * state.along}
            ry={state.radius * state.across}
            transform={`rotate(${state.rotation} ${state.x} ${state.y})`}
            fill={color}
          />
        ) : null}
      </svg>
      {placed ? (
        <div
          style={{
            position: "absolute",
            left: `${state.left}%`,
            top: `${state.top}%`,
            width: "max-content",
            transform: state.transform,
            transformOrigin: "50% 50%",
          }}
        >
          {children}
        </div>
      ) : null}
    </div>
  );
}

